use vstd::prelude::*;

verus! {

fn numpy_insert<T>(arr: Vec<T>, idx: usize, value: T) -> (result: Vec<T>)
    requires
        idx <= arr.len(),
    ensures
        result.len() == arr.len() + 1,
        // elements before idx are preserved
        forall|i: int| 0 <= i < idx as int ==> result[i] == arr[i],
        // inserted element
        result[idx as int] == value,
        // elements at/after idx are shifted right by 1
        forall|i: int| idx as int <= i < arr.len() as int ==> result[(i + 1) as int] == arr[i],
{
    assert!(idx <= arr.len(), "idx must be in 0..=arr.len()");

    let mut result = Vec::with_capacity(arr.len() + 1);

    // Move elements before idx
    result.extend(arr[..idx].into_iter());
    // Insert value at idx
    result.push(value);
    // Move elements at/after idx (shifted by one)
    result.extend(arr[idx..].into_iter());

    result
}

} // verus!

